<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/certificate-auth.php';
$user=fleet_cert_require_user();
if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET')json_response(['ok'=>false,'message'=>'Method not allowed.'],405);
$id=(int)($_GET['id']??0);if($id<1)json_response(['ok'=>false,'message'=>'Certificate submission was not found.'],400);
try{
 $db=fleet_db();
 $q=$db->prepare("SELECT cs.id submission_id,cs.asset_id,cs.asset_scope,cs.registration_snapshot,cs.driver_name_snapshot,ct.display_name certificate_type_name,cs.status submission_status,cs.issue_date,cs.expiry_date,cs.original_filename,cs.mime_type,cs.document_storage_name,a.primary_identifier,a.make,a.model,a.manufacture_year,a.registration_status,a.last_seen_at,t.type_name asset_type_name,s.status_name current_status,y.yard_name location_name,ai.source_note FROM certificate_submissions cs JOIN certificate_types ct ON ct.id=cs.certificate_type_id LEFT JOIN assets a ON a.id=cs.asset_id LEFT JOIN asset_types t ON t.id=a.asset_type_id LEFT JOIN asset_statuses s ON s.id=a.current_status_id LEFT JOIN yards y ON y.id=a.current_yard_id LEFT JOIN asset_identifiers ai ON ai.asset_id=a.id AND ai.is_primary=1 WHERE cs.id=? LIMIT 1");
 $q->execute([$id]);$row=$q->fetch();if(!$row)json_response(['ok'=>false,'message'=>'Certificate submission was not found.'],404);
 if($row['asset_id']===null)json_response(['ok'=>true,'asset'=>null,'submission'=>['id'=>(int)$row['submission_id'],'asset_scope'=>$row['asset_scope'],'registration'=>$row['registration_snapshot'],'certificate_type_name'=>$row['certificate_type_name'],'status'=>$row['submission_status'],'issue_date'=>$row['issue_date'],'expiry_date'=>$row['expiry_date'],'original_filename'=>$row['original_filename'],'document_storage_name'=>$row['document_storage_name']],'linked_assets'=>[]]);
 $assetId=(int)$row['asset_id'];$driver=null;$locationName=$row['location_name'];$locationSource=$locationName?'Current yard':'Source worksheet';
 if(!$locationName&&preg_match('/^([^\/]+)\/([^\/]+) row (\d+) col ([A-Z]+)/',(string)$row['source_note'],$sourceMatch)){$sourceCode=$sourceMatch[1];$sheetName=$sourceMatch[2];$sourceRow=(int)$sourceMatch[3];if(str_starts_with($sheetName,'Ngwerere_')||$sheetName==='Unregistered_Ngwerere')$locationName='Ngwerere';elseif($sheetName==='Registered_21Miles')$locationName='21 Miles Yard';elseif(str_starts_with($sheetName,'Nakonde_')){$source=$db->prepare('SELECT id FROM spreadsheet_sources WHERE source_code=? LIMIT 1');$source->execute([$sourceCode]);$sourceId=(int)$source->fetchColumn();$sheet=$db->prepare('SELECT id FROM spreadsheet_sheets WHERE source_id=? AND sheet_name=? LIMIT 1');$sheet->execute([$sourceId,$sheetName]);$sheetId=(int)$sheet->fetchColumn();$runMatch=[];preg_match('/\(run (\d+)\)/',(string)$row['source_note'],$runMatch);$runId=(int)($runMatch[1]??0);if($sheetId&&$runId){$raw=$db->prepare('SELECT raw_data FROM spreadsheet_source_row_versions WHERE sync_run_id=? AND sheet_id=? AND source_row_number=? LIMIT 1');$raw->execute([$runId,$sheetId,$sourceRow]);$cells=json_decode((string)($raw->fetchColumn()?:'[]'),true)?:[];$yardIndex=$sheetName==='Nakonde_Tankers_unregistered'?3:4;$locationName=trim((string)($cells[$yardIndex]??''))?:'Nakonde';}else $locationName='Nakonde';}}
 if($row['asset_scope']==='HORSE'){$d=$db->prepare('SELECT dr.full_name,dr.phone FROM asset_driver_assignments da JOIN drivers dr ON dr.id=da.driver_id WHERE da.asset_id=? AND da.assigned_to IS NULL AND dr.is_active=1 ORDER BY da.assigned_from DESC LIMIT 1');$d->execute([$assetId]);$driver=$d->fetch()?:null;}
 $linked=[];
 if($row['asset_scope']==='HORSE'){$l=$db->prepare("SELECT a2.primary_identifier,t2.type_name FROM asset_attachments aa JOIN assets a2 ON a2.id=aa.trailer_asset_id JOIN asset_types t2 ON t2.id=a2.asset_type_id WHERE aa.head_asset_id=? AND aa.attached_to IS NULL ORDER BY aa.attached_from DESC");$l->execute([$assetId]);$linked=$l->fetchAll();}
 elseif(in_array($row['asset_scope'],['TANKER','FLATBED'],true)){$l=$db->prepare("SELECT a2.primary_identifier,t2.type_name FROM asset_attachments aa JOIN assets a2 ON a2.id=aa.head_asset_id JOIN asset_types t2 ON t2.id=a2.asset_type_id WHERE aa.trailer_asset_id=? AND aa.attached_to IS NULL ORDER BY aa.attached_from DESC");$l->execute([$assetId]);$linked=$l->fetchAll();}
 json_response(['ok'=>true,'submission'=>['id'=>(int)$row['submission_id'],'asset_scope'=>$row['asset_scope'],'registration'=>$row['registration_snapshot'],'certificate_type_name'=>$row['certificate_type_name'],'status'=>$row['submission_status'],'issue_date'=>$row['issue_date'],'expiry_date'=>$row['expiry_date'],'original_filename'=>$row['original_filename'],'document_storage_name'=>$row['document_storage_name']],'asset'=>['id'=>$assetId,'registration'=>$row['primary_identifier']?:$row['registration_snapshot'],'asset_type_name'=>$row['asset_type_name']?:cert_asset_scope_label($row['asset_scope']),'make'=>$row['make'],'model'=>$row['model'],'manufacture_year'=>$row['manufacture_year'],'registration_status'=>$row['registration_status'],'current_status'=>$row['current_status'],'location_name'=>$locationName?:'Not recorded','location_source'=>$locationSource,'last_seen_at'=>$row['last_seen_at'],'driver'=>$driver],'linked_assets'=>$linked]);
}catch(Throwable $e){error_log('Certificate asset details: '.$e->getMessage());json_response(['ok'=>false,'message'=>'Could not load asset details. Check the server log.'],500);}
function cert_asset_scope_label(string $scope):string{return match($scope){'HORSE'=>'Horse','TANKER'=>'Tanker','FLATBED'=>'Flatbed',default=>$scope};}
